import { io, type Socket } from "socket.io-client";
import { onMounted, onUnmounted } from "vue";

let socket: Socket | null = null;

/**
 * Attaches an event listener to the socket if it is connected.
 * @param socket_ - The socket instance to listen on.
 * @param event - Event name to subscribe to.
 * @param handler - Callback invoked with the event payload.
 */
function on<T>(socket_: Socket | null, event: string, handler: (data: T) => void) {
  socket_?.on(event, handler);
}

/**
 * Composable that manages a Socket.IO connection scoped to a simulation run.
 * @param runId - ID of the run to subscribe to, or null to skip connecting.
 * @returns An object with an `on` helper to register typed event listeners.
 */
export function useSocket(runId: string | null) {
  onMounted(() => {
    if (runId === null || runId === "") return;
    const backendUrl: string = (import.meta.env.CHRONOS_BACKEND_URL as string | undefined) ?? "http://localhost:3000";
    socket = io(backendUrl);
    socket.emit("subscribe:run", runId);
  });

  onUnmounted(() => {
    if (socket !== null && runId !== null && runId !== "") socket.emit("unsubscribe:run", runId);
    socket?.disconnect();
    socket = null;
  });

  return {
    /**
     * Registers a typed listener for the given socket event.
     * @param event - Event name to subscribe to.
     * @param handler - Callback invoked with the typed event payload.
     */
    on: <T>(event: string, handler: (data: T) => void) => {
      on<T>(socket, event, handler);
    },
  };
}

