import { defineStore } from "pinia";
import { ref } from "vue";
import { simulationApi, type CreateRunPayload } from "@/api/simulation.api";
import type { SimulationRun } from "@/types/domain";

export const useRunStore = defineStore("run", () => {
  const activeRun = ref<SimulationRun | null>(null);
  const loading = ref(false);
  const error = ref<string | null>(null);

  /**
   * Creates a new simulation run with the given configuration.
   * @param payload - Run creation parameters.
   */
  async function createRun(payload: CreateRunPayload) {
    loading.value = true;
    error.value = null;
    try {
      activeRun.value = await simulationApi.createRun(payload);
    }
    catch (error_) {
      error.value = String(error_);
    }
    finally {
      loading.value = false;
    }
  }

  /**
   *
   */
  async function start() {
    if (!activeRun.value) return;
    activeRun.value = await simulationApi.start(activeRun.value.runId);
  }

  /**
   *
   */
  async function pause() {
    if (!activeRun.value) return;
    activeRun.value = await simulationApi.pause(activeRun.value.runId);
  }

  /**
   *
   */
  async function reset() {
    if (!activeRun.value) return;
    activeRun.value = await simulationApi.reset(activeRun.value.runId);
  }

  /**
   *
   */
  async function refresh() {
    if (!activeRun.value) return;
    activeRun.value = await simulationApi.getStatus(activeRun.value.runId);
  }

  return { activeRun, loading, error, createRun, start, pause, reset, refresh };
}, { persist: true });

import { defineStore } from "pinia";
import { ref } from "vue";
import { stockApi } from "@/api/stock.api";
import type { SimStock } from "@/types/domain";

export const useStockStore = defineStore("stock", () => {
  const stocks = ref<Array<SimStock>>([]);
  const loading = ref(false);

  /**
   *
   */
  async function fetch() {
    loading.value = true;
    try {
      stocks.value = await stockApi.getAll();
    }
    finally {
      loading.value = false;
    }
  }

  /**
   * Inserts or replaces a stock entry received via socket update.
   * @param updated - The updated stock object from the server.
   */
  function applySocketUpdate(updated: SimStock) {
    const index = stocks.value.findIndex(s => s.material === updated.material);
    if (index === -1) {
      stocks.value.push(updated);
    }
    else {
      stocks.value.splice(index, 1, updated);
    }
  }

  return { stocks, loading, fetch, applySocketUpdate };
});

import { defineStore } from "pinia";
import { ref } from "vue";
import { workRequestsApi } from "@/api/work-requests.api";
import type { CreateWorkRequestPayload } from "@/api/work-requests.api";
import type { SimWorkRequest } from "@/types/domain";

export const useWorkRequestsStore = defineStore("workRequests", () => {
  const workRequests = ref<Array<SimWorkRequest>>([]);
  const loading = ref(false);

  /**
   * Loads work requests from the API, optionally filtered by run.
   * @param runId - Optional run ID to filter work requests.
   * @returns A promise that resolves when the work requests have been loaded.
   */
  async function fetch(runId?: string): Promise<void> {
    loading.value = true;
    try {
      workRequests.value = await workRequestsApi.list({ runId });
    }
    finally {
      loading.value = false;
    }
  }

  /**
   * Creates a new work request and appends it to the local list.
   * @param payload - The work request creation payload.
   * @returns The created work request.
   */
  async function create(payload: CreateWorkRequestPayload): Promise<SimWorkRequest> {
    const created = await workRequestsApi.create(payload);
    workRequests.value.push(created);
    return created;
  }

  /**
   * Updates an existing work request and reflects the change in the local list.
   * @param id - ID of the work request to update.
   * @param payload - Partial fields to update.
   * @returns The updated work request.
   */
  async function update(
    id: string,
    payload: Partial<Pick<SimWorkRequest, "orderedQuantity" | "startTime" | "endTime" | "priority">>,
  ): Promise<SimWorkRequest> {
    const updated = await workRequestsApi.update(id, payload);
    const index = workRequests.value.findIndex(w => w.id === id);
    if (index !== -1) workRequests.value.splice(index, 1, updated);
    return updated;
  }

  /**
   * Cancels a work request and reflects the change in the local list.
   * @param id - ID of the work request to cancel.
   * @returns The cancelled work request.
   */
  async function cancel(id: string): Promise<SimWorkRequest> {
    const cancelled = await workRequestsApi.cancel(id);
    const index = workRequests.value.findIndex(w => w.id === id);
    if (index !== -1) workRequests.value.splice(index, 1, cancelled);
    return cancelled;
  }

  /**
   * Applies a real-time socket update to the local work request list.
   * @param updated - The updated work request received from the socket.
   */
  function applySocketUpdate(updated: SimWorkRequest): void {
    const index = workRequests.value.findIndex(w => w.id === updated.id);
    if (index === -1) {
      workRequests.value.push(updated);
    }
    else {
      workRequests.value.splice(index, 1, updated);
    }
  }

  return { workRequests, loading, fetch, create, update, cancel, applySocketUpdate };
});

